/**
 * Finding the right YouTube video for a song. The ranking rules are plain
 * functions (checked in youtube.test.ts); `searchVideos` is the only part
 * that talks to YouTube.
 *
 * A search costs 100 of the day's 10,000 free units (about 100 searches), so
 * it only runs when you open "Choose a video", and the choice is saved.
 */

export type VideoWarning = "lyrics" | "version" | "length";

export interface VideoCandidate {
  videoId: string;
  title: string;
  channel: string;
  thumbnail: string | null;
  durationMs: number;
  /** An auto-generated upload (cover picture only, clean title): the best kind. */
  topic: boolean;
  warning: VideoWarning | null;
}

/** Words that mean the video shows the lyrics on screen. */
const LYRICS_VIDEO = /\b(lyrics?|lyric video|karaoke|sing[- ]?along|letras?|con letra)\b/i;
/** Other versions of a song that won't match its lyrics' timing. */
const OTHER_VERSION =
  /\b(live|en vivo|cover|remix|instrumental|acoustic|sped up|slowed|nightcore|8d|reverb|reaction)\b/i;

/** A gap this big between the video and the song's length means a different version. */
const LENGTH_WARN_MS = 20_000;

export function decodeEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)));
}

/** A song's title without the extras that only get in the way of a search. */
export function cleanSongTitle(title: string): string {
  return title
    .replace(
      /\s*[([][^)\]]*\b(feat|ft|with|remaster(ed)?|version|edit|mix|live|mono|stereo|deluxe|from)\b[^)\]]*[)\]]/gi,
      ""
    )
    .replace(/\s+-\s+.*\b(remaster(ed)?|version|edit|mix|mono|stereo)\b.*$/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

export function searchQuery(title: string, primaryArtist: string): string {
  return `${primaryArtist} ${cleanSongTitle(title)}`.trim();
}

/** "PT3M33S" → milliseconds. */
export function parseDuration(iso: string): number {
  const m = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso);
  if (!m) return 0;
  return ((Number(m[1] ?? 0) * 60 + Number(m[2] ?? 0)) * 60 + Number(m[3] ?? 0)) * 1000;
}

export function looksLikeLyricsVideo(videoTitle: string): boolean {
  return LYRICS_VIDEO.test(videoTitle);
}

/** A different version of the song, unless the song's own title says so too. */
export function looksLikeOtherVersion(videoTitle: string, songTitle: string): boolean {
  const found = OTHER_VERSION.exec(videoTitle);
  return Boolean(found) && !new RegExp(`\\b${found![0]}\\b`, "i").test(songTitle);
}

/** YouTube's own artist channels ("Name - Topic") and "Provided to YouTube by" uploads. */
export function isAutoGenerated(channel: string, description: string): boolean {
  return /\s-\s+Topic$/i.test(channel) || /^Provided to YouTube by/i.test(description.trim());
}

export function warningFor(
  video: { title: string; channel?: string; durationMs: number },
  song: { title: string; durationMs: number }
): VideoWarning | null {
  // Lyrics channels ("Amazing Lyrics") often leave the word out of the title.
  if (looksLikeLyricsVideo(`${video.title} ${video.channel ?? ""}`)) return "lyrics";
  if (looksLikeOtherVersion(video.title, song.title)) return "version";
  // A song length of 0 means it isn't known (a song being added): nothing to compare.
  if (
    song.durationMs > 0 &&
    video.durationMs > 0 &&
    Math.abs(video.durationMs - song.durationMs) > LENGTH_WARN_MS
  ) {
    return "length";
  }
  return null;
}

function score(c: VideoCandidate, songDurationMs: number): number {
  let points = c.topic ? 3 : 0;
  if (c.warning === "lyrics") points -= 6;
  else if (c.warning === "version") points -= 4;
  else if (c.warning === "length") points -= 2;
  if (songDurationMs > 0) {
    const gap = Math.abs(c.durationMs - songDurationMs);
    if (gap <= 3_000) points += 2;
    else if (gap <= 10_000) points += 1;
  }
  return points;
}

/** Best first. Ties keep YouTube's own order (the sort is stable). */
export function rankCandidates(
  candidates: VideoCandidate[],
  song: { durationMs: number }
): VideoCandidate[] {
  return [...candidates].sort((a, b) => score(b, song.durationMs) - score(a, song.durationMs));
}

/** What YouTube says about where and how a video may be played. */
export interface PlayRules {
  embeddable?: boolean;
  privacyStatus?: string;
  /** Countries allowed, or countries blocked (YouTube gives one of the two). */
  regionRestriction?: { allowed?: string[]; blocked?: string[] };
}

/**
 * Whether a video can play in the game's corner player. A video flagged as
 * embeddable can still be blocked in your country, so the region counts when
 * it's known (it comes from the browser's language, a good guess, not proof).
 */
export function canPlayInGame(rules: PlayRules, region: string | null): boolean {
  if (rules.embeddable === false) return false;
  if (rules.privacyStatus && rules.privacyStatus !== "public") return false;
  const restriction = rules.regionRestriction;
  if (region && restriction) {
    if (restriction.blocked?.includes(region)) return false;
    if (restriction.allowed && !restriction.allowed.includes(region)) return false;
  }
  return true;
}

export type YouTubeFailure = "no_key" | "quota" | "not_found" | "failed";

export class YouTubeError extends Error {
  code: YouTubeFailure;
  constructor(code: YouTubeFailure) {
    super(`YouTube: ${code}`);
    this.code = code;
  }
}

const API = "https://www.googleapis.com/youtube/v3";

async function call(path: string, params: Record<string, string>): Promise<unknown> {
  const key = process.env.YOUTUBE_API_KEY;
  if (!key) throw new YouTubeError("no_key");
  let res: Response;
  try {
    res = await fetch(`${API}/${path}?${new URLSearchParams({ ...params, key })}`, {
      cache: "no-store",
    });
  } catch {
    throw new YouTubeError("failed");
  }
  if (res.ok) return res.json();
  const body = await res.json().catch(() => null);
  const reason = body?.error?.errors?.[0]?.reason;
  console.error(`[youtube] ${path} answered ${res.status} (${reason ?? "no reason"})`);
  throw new YouTubeError(reason === "quotaExceeded" || reason === "rateLimitExceeded" ? "quota" : "failed");
}

interface SearchItem {
  id?: { videoId?: string };
  snippet?: {
    title?: string;
    channelTitle?: string;
    description?: string;
    thumbnails?: { medium?: { url?: string }; default?: { url?: string } };
  };
}

/** The best three videos for a song, best first, each with a warning if it looks wrong. */
export async function searchVideos(
  song: { title: string; primaryArtist: string; durationMs: number },
  /** Two-letter country, e.g. "ES", if known. */
  region: string | null = null
): Promise<VideoCandidate[]> {
  const found = (await call("search", {
    part: "snippet",
    type: "video",
    videoEmbeddable: "true",
    videoSyndicated: "true",
    videoCategoryId: "10", // Music
    maxResults: "10",
    q: searchQuery(song.title, song.primaryArtist),
    ...(region ? { regionCode: region } : {}),
  })) as { items?: SearchItem[] };

  const results = (found.items ?? []).filter((i) => i.id?.videoId && i.snippet);
  if (results.length === 0) return [];

  const details = (await call("videos", {
    part: "contentDetails,status",
    id: results.map((i) => i.id!.videoId!).join(","),
  })) as {
    items?: {
      id: string;
      contentDetails?: { duration?: string; regionRestriction?: PlayRules["regionRestriction"] };
      status?: { embeddable?: boolean; privacyStatus?: string };
    }[];
  };
  const lengths = new Map(
    (details.items ?? []).map((d) => [d.id, parseDuration(d.contentDetails?.duration ?? "")])
  );
  const playable = new Set(
    (details.items ?? [])
      .filter((d) =>
        canPlayInGame(
          {
            embeddable: d.status?.embeddable,
            privacyStatus: d.status?.privacyStatus,
            regionRestriction: d.contentDetails?.regionRestriction,
          },
          region
        )
      )
      .map((d) => d.id)
  );
  const items = results.filter((i) => playable.has(i.id!.videoId!));

  const candidates = items.map((i): VideoCandidate => {
    const title = decodeEntities(i.snippet!.title ?? "");
    const channel = decodeEntities(i.snippet!.channelTitle ?? "");
    const durationMs = lengths.get(i.id!.videoId!) ?? 0;
    return {
      videoId: i.id!.videoId!,
      title,
      channel,
      thumbnail: i.snippet!.thumbnails?.medium?.url ?? i.snippet!.thumbnails?.default?.url ?? null,
      durationMs,
      topic: isAutoGenerated(channel, i.snippet!.description ?? ""),
      warning: warningFor({ title, channel, durationMs }, song),
    };
  });
  return rankCandidates(candidates, song).slice(0, 3);
}

// ---- Adding songs from YouTube links and playlists ----

const VIDEO_ID = /^[\w-]{11}$/;
const PLAYLIST_ID = /^[\w-]{10,64}$/;
const YOUTUBE_HOSTS = new Set([
  "youtube.com",
  "www.youtube.com",
  "m.youtube.com",
  "music.youtube.com",
  "youtu.be",
]);

/** The video and/or playlist a pasted YouTube address points to; null if it isn't one. */
export function parseYouTubeLink(text: string): { videoId?: string; playlistId?: string } | null {
  let url: URL;
  try {
    url = new URL(text.trim());
  } catch {
    return null;
  }
  if (!/^https?:$/.test(url.protocol) || !YOUTUBE_HOSTS.has(url.hostname)) return null;

  const list = url.searchParams.get("list");
  const playlistId = list && PLAYLIST_ID.test(list) ? list : undefined;

  let videoId: string | undefined;
  if (url.hostname === "youtu.be") {
    videoId = url.pathname.split("/")[1];
  } else if (url.pathname === "/watch") {
    videoId = url.searchParams.get("v") ?? undefined;
  } else {
    const m = /^\/(?:embed|shorts|live|v)\/([\w-]{11})/.exec(url.pathname);
    videoId = m?.[1];
  }
  if (videoId && !VIDEO_ID.test(videoId)) videoId = undefined;

  // A /playlist address is the whole playlist; a /watch address with a list is that one video.
  if (url.pathname === "/playlist") return playlistId ? { playlistId } : null;
  if (videoId) return { videoId, ...(playlistId ? { playlistId } : {}) };
  return playlistId ? { playlistId } : null;
}

/** A video title without the labels that aren't part of the song's name. */
export function cleanVideoTitle(title: string): string {
  return title
    .replace(
      /\s*[([][^)\]]*\b(official|video|audio|lyrics?|visuali[sz]er|hd|4k|hq|mv|m\/v|clip|letra)\b[^)\]]*[)\]]/gi,
      ""
    )
    .replace(/\s*[|｜].*$/, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

/**
 * A song's title and artist from its video: a "Name - Topic" channel gives
 * the artist outright; otherwise "Artist - Title" is split, else the channel
 * is the artist.
 */
export function songFromVideo(video: { title: string; channel: string }): {
  title: string;
  artist: string;
  primaryArtist: string;
} {
  const cleaned = cleanVideoTitle(video.title);
  let title = cleaned;
  let artist = video.channel.replace(/\s*-\s*Topic$/i, "").replace(/VEVO$/i, "").trim();
  if (!/\s-\s+Topic$/i.test(video.channel)) {
    const split = /^(.+?)\s+[-–—]\s+(.+)$/.exec(cleaned);
    if (split) {
      artist = split[1].trim();
      title = split[2].trim();
    }
  }
  const primaryArtist = artist.split(/\s*(?:,|&|\bfeat\.?\s|\bft\.?\s|\bx\b)\s*/i)[0].trim() || artist;
  return { title: title || video.title, artist: artist || video.channel, primaryArtist };
}

export function formatDuration(ms: number): string {
  const total = Math.round(ms / 1000);
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
}

/** What the library keeps for a song that comes from a video. */
export interface VideoSong {
  videoId: string;
  title: string;
  artist: string;
  primaryArtist: string;
  durationMs: number;
  /** The video's picture: album art on a Topic upload. */
  cover: string | null;
  /** Whether YouTube says it can play in the game here (embeddable, public, not blocked in the country). */
  playable: boolean;
}

interface VideoItem {
  id: string;
  snippet?: {
    title?: string;
    channelTitle?: string;
    thumbnails?: { medium?: { url?: string }; high?: { url?: string }; default?: { url?: string } };
  };
  contentDetails?: { duration?: string; regionRestriction?: PlayRules["regionRestriction"] };
  status?: { embeddable?: boolean; privacyStatus?: string };
}

/** Details for up to 50 videos at once (1 unit of the free quota). */
export async function getVideoSongs(ids: string[], region: string | null = null): Promise<VideoSong[]> {
  if (ids.length === 0) return [];
  const got = (await call("videos", {
    part: "snippet,contentDetails,status",
    id: ids.slice(0, 50).join(","),
  })) as { items?: VideoItem[] };
  return (got.items ?? []).map((v) => {
    const channel = decodeEntities(v.snippet?.channelTitle ?? "");
    const parsed = songFromVideo({ title: decodeEntities(v.snippet?.title ?? ""), channel });
    const pics = v.snippet?.thumbnails;
    return {
      videoId: v.id,
      ...parsed,
      durationMs: parseDuration(v.contentDetails?.duration ?? ""),
      cover: pics?.medium?.url ?? pics?.high?.url ?? pics?.default?.url ?? null,
      playable: canPlayInGame(
        {
          embeddable: v.status?.embeddable,
          privacyStatus: v.status?.privacyStatus,
          regionRestriction: v.contentDetails?.regionRestriction,
        },
        region
      ),
    };
  });
}

/** A playlist reads at most this many songs: 4 pages of 50. */
export const MAX_PLAYLIST_SONGS = 200;

/** A public or unlisted playlist: its name, picture and songs, in order. */
export async function getPlaylistSongs(
  playlistId: string,
  region: string | null = null
): Promise<{ name: string; cover: string | null; songs: VideoSong[]; skipped: number; tooLong: boolean }> {
  const info = (await call("playlists", { part: "snippet", id: playlistId })) as {
    items?: { snippet?: { title?: string; thumbnails?: { medium?: { url?: string } } } }[];
  };
  const head = info.items?.[0];
  if (!head) throw new YouTubeError("not_found");

  const ids: string[] = [];
  let pageToken = "";
  let tooLong = false;
  while (true) {
    const page = (await call("playlistItems", {
      part: "contentDetails",
      maxResults: "50",
      playlistId,
      ...(pageToken ? { pageToken } : {}),
    })) as { items?: { contentDetails?: { videoId?: string } }[]; nextPageToken?: string };
    for (const item of page.items ?? []) {
      const id = item.contentDetails?.videoId;
      if (id && VIDEO_ID.test(id)) ids.push(id);
    }
    if (!page.nextPageToken) break;
    if (ids.length >= MAX_PLAYLIST_SONGS) {
      tooLong = true;
      break;
    }
    pageToken = page.nextPageToken;
  }

  const wanted = ids.slice(0, MAX_PLAYLIST_SONGS);
  const songs: VideoSong[] = [];
  for (let i = 0; i < wanted.length; i += 50) {
    songs.push(...(await getVideoSongs(wanted.slice(i, i + 50), region)));
  }
  // YouTube drops private and deleted videos from the details, so fewer come back than were listed.
  const byId = new Map(songs.map((s) => [s.videoId, s]));
  const ordered = wanted.flatMap((id) => (byId.has(id) && byId.get(id)!.playable ? [byId.get(id)!] : []));
  return {
    name: decodeEntities(head.snippet?.title ?? "YouTube playlist"),
    cover: head.snippet?.thumbnails?.medium?.url ?? null,
    songs: ordered,
    skipped: wanted.length - ordered.length,
    tooLong,
  };
}

/** The HTTP status a failure is answered with. */
export function failureStatus(code: YouTubeFailure): number {
  return code === "no_key" ? 500 : code === "not_found" ? 404 : 502;
}
